bool VisibilityBvh3D::Valid(MeshBounds3D value){return std::isfinite(value.radius)&&value.radius>=0&&std::isfinite(value.center.x)&&std::isfinite(value.center.y)&&std::isfinite(value.center.z)&&std::isfinite(value.extents.x)&&std::isfinite(value.extents.y)&&std::isfinite(value.extents.z)&&value.extents.x>=0&&value.extents.y>=0&&value.extents.z>=0;}
MeshBounds3D VisibilityBvh3D::Merge(MeshBounds3D a,MeshBounds3D b){const auto axis=[](float ac,float ae,float bc,float be){const double low=(std::min)(double(ac)-ae,double(bc)-be),high=(std::max)(double(ac)+ae,double(bc)+be);return std::pair<float,float>{float((low+high)*.5),float((high-low)*.5)};};const auto x=axis(a.center.x,a.extents.x,b.center.x,b.extents.x),y=axis(a.center.y,a.extents.y,b.center.y,b.extents.y),z=axis(a.center.z,a.extents.z,b.center.z,b.extents.z);const Vec3 center{x.first,y.first,z.first},extents{x.second,y.second,z.second};return{center,Length(extents),extents};}
std::uint32_t VisibilityBvh3D::BuildNode(std::uint32_t first,std::uint32_t count,std::uint32_t parent){MeshBounds3D bounds=entries_[first].bounds;Vec3 low=bounds.center,high=low;for(std::uint32_t i=1;i<count;++i){bounds=Merge(bounds,entries_[first+i].bounds);const Vec3 c=entries_[first+i].bounds.center;low.x=(std::min)(low.x,c.x);low.y=(std::min)(low.y,c.y);low.z=(std::min)(low.z,c.z);high.x=(std::max)(high.x,c.x);high.y=(std::max)(high.y,c.y);high.z=(std::max)(high.z,c.z);}const std::uint32_t index=std::uint32_t(nodes_.size());nodes_.push_back({bounds,parent,0,0,first,count,count});if(count<=8){for(std::uint32_t i=0;i<count;++i)entries_[first+i].leaf=index;return index;}const Vec3 spread=high-low;const int axis=spread.y>spread.x?(spread.z>spread.y?2:1):(spread.z>spread.x?2:0);const std::uint32_t half=count/2,mid=first+half;std::nth_element(entries_.begin()+first,entries_.begin()+mid,entries_.begin()+first+count,[axis](const Entry& a,const Entry& b){return axis==0?a.bounds.center.x<b.bounds.center.x:axis==1?a.bounds.center.y<b.bounds.center.y:a.bounds.center.z<b.bounds.center.z;});const std::uint32_t left=BuildNode(first,half,index),right=BuildNode(mid,count-half,index);nodes_[index].left=left;nodes_[index].right=right;nodes_[index].count=0;return index;}
bool VisibilityBvh3D::Build(std::span<const VisibilityBvhItem3D> items){if(items.size()>(std::numeric_limits<std::uint32_t>::max)()/2)return false;try{VisibilityBvh3D candidate;candidate.retainedObjects_=retainedObjects_;candidate.entries_.reserve(items.size());candidate.nodes_.reserve(items.empty()?0:items.size()*2-1);candidate.keyToEntry_.reserve(items.size());candidate.traversal_.reserve(items.empty()?0:items.size()*2-1);candidate.candidates_.reserve(items.size());candidate.refitBounds_.reserve(items.empty()?0:items.size()*2-1);for(const auto& item:items){if(!item.key||!Valid(item.bounds)||!candidate.keyToEntry_.emplace(item.key,0).second)return false;MeshBounds3D bounds=item.bounds;bounds.extents.x=(std::max)(bounds.extents.x,bounds.radius);bounds.extents.y=(std::max)(bounds.extents.y,bounds.radius);bounds.extents.z=(std::max)(bounds.extents.z,bounds.radius);candidate.entries_.push_back({item.key,bounds,{},item.payload});}if(!candidate.entries_.empty())candidate.BuildNode(0,std::uint32_t(candidate.entries_.size()),~0u);if(std::any_of(candidate.nodes_.begin(),candidate.nodes_.end(),[](const Node& node){return !Valid(node.bounds);}))return false;candidate.refitBounds_.resize(candidate.nodes_.size());candidate.keyToEntry_.clear();candidate.keyToEntry_.reserve(candidate.entries_.size());for(std::uint32_t index=0;index<candidate.entries_.size();++index)candidate.keyToEntry_.emplace(candidate.entries_[index].key,index);entries_.swap(candidate.entries_);nodes_.swap(candidate.nodes_);keyToEntry_.swap(candidate.keyToEntry_);traversal_.swap(candidate.traversal_);candidates_.swap(candidate.candidates_);refitBounds_.swap(candidate.refitBounds_);++stats_.builds;stats_.objects=entries_.size();stats_.nodes=nodes_.size();return true;}catch(const std::bad_alloc&){return false;}}
bool VisibilityBvh3D::Update(VisibilityEntityKey3D key,MeshBounds3D bounds){if(!key||!Valid(bounds))return false;const auto found=keyToEntry_.find(key);if(found==keyToEntry_.end())return false;bounds.extents.x=(std::max)(bounds.extents.x,bounds.radius);bounds.extents.y=(std::max)(bounds.extents.y,bounds.radius);bounds.extents.z=(std::max)(bounds.extents.z,bounds.radius);Entry& entry=entries_[found->second];entry.pendingBounds=bounds;entry.dirty=true;return true;}
bool VisibilityBvh3D::Refit(){if(nodes_.empty())return true;std::size_t changed{};for(const Entry& entry:entries_)changed+=entry.dirty;if(!changed)return true;if(refitBounds_.size()!=nodes_.size())return false;for(std::size_t i=0;i<nodes_.size();++i)refitBounds_[i]=nodes_[i].bounds;for(const Entry& changedEntry:entries_)if(changedEntry.dirty){const Node& leaf=nodes_[changedEntry.leaf];const auto boundsAt=[&](std::uint32_t offset)->MeshBounds3D{const Entry& value=entries_[leaf.first+offset];return value.dirty?value.pendingBounds:value.bounds;};MeshBounds3D bounds=boundsAt(0);for(std::uint32_t i=1;i<leaf.count;++i)bounds=Merge(bounds,boundsAt(i));if(!Valid(bounds))return false;refitBounds_[changedEntry.leaf]=bounds;}for(std::size_t i=nodes_.size();i-->0;)if(!nodes_[i].count){refitBounds_[i]=Merge(refitBounds_[nodes_[i].left],refitBounds_[nodes_[i].right]);if(!Valid(refitBounds_[i]))return false;}for(std::size_t i=0;i<nodes_.size();++i)nodes_[i].bounds=refitBounds_[i];for(Entry& entry:entries_)if(entry.dirty){entry.bounds=entry.pendingBounds;entry.dirty=false;}++stats_.refits;stats_.refittedLeaves=changed;return true;}
std::span<const std::uint32_t> VisibilityBvh3D::Query(const VisibilityBvhQuery3D& query)const{traversal_.clear();candidates_.clear();++stats_.queries;stats_.nodesTested=stats_.nodesRejected=stats_.distanceRejectedObjects=stats_.frustumRejectedObjects=0;if(nodes_.empty())return candidates_;const auto rejection=[&](MeshBounds3D bounds){const float distance=Length(bounds.center-query.camera.position)-bounds.radius;if(query.shadowDistance>0&&distance<=query.shadowDistance)return 0;if(query.maximumDistance>0&&distance>query.maximumDistance)return 1;if(query.frustumCulling&&!SphereIntersectsFrustum(bounds.center,bounds.radius,query.camera,query.aspect))return 2;return 0;};traversal_.push_back(0);while(!traversal_.empty()){const std::uint32_t index=traversal_.back();traversal_.pop_back();const Node& node=nodes_[index];++stats_.nodesTested;const int rejected=rejection(node.bounds);if(rejected){++stats_.nodesRejected;(rejected==1?stats_.distanceRejectedObjects:stats_.frustumRejectedObjects)+=node.subtreeCount;continue;}if(node.count){for(std::uint32_t i=0;i<node.count;++i){const Entry& entry=entries_[node.first+i];const int entryRejected=rejection(entry.bounds);if(!entryRejected)candidates_.push_back(entry.payload);else ++(entryRejected==1?stats_.distanceRejectedObjects:stats_.frustumRejectedObjects);}}else{traversal_.push_back(node.left);traversal_.push_back(node.right);}}std::sort(candidates_.begin(),candidates_.end());stats_.candidates=candidates_.size();return candidates_;}
void VisibilityBvh3D::Clear(){entries_.clear();keyToEntry_.clear();nodes_.clear();traversal_.clear();candidates_.clear();refitBounds_.clear();stats_.objects=stats_.nodes=stats_.candidates=0;}
bool VisibilityBvh3D::Reserve(std::size_t objects){if(objects>(std::numeric_limits<std::size_t>::max)()/2+1)return false;const std::size_t nodes=objects?objects*2-1:0;try{entries_.reserve(objects);nodes_.reserve(nodes);traversal_.reserve(nodes);candidates_.reserve(objects);refitBounds_.reserve(nodes);keyToEntry_.reserve(objects);retainedObjects_=objects;return true;}catch(const std::bad_alloc&){return false;}}
ReusableMemoryStats VisibilityBvh3D::MemoryStats()const{const std::size_t mapBytes=keyToEntry_.bucket_count()*sizeof(void*)+keyToEntry_.size()*(sizeof(std::pair<const VisibilityEntityKey3D,std::uint32_t>)+sizeof(void*)*2),bytes=entries_.capacity()*sizeof(Entry)+nodes_.capacity()*sizeof(Node)+traversal_.capacity()*sizeof(std::uint32_t)+candidates_.capacity()*sizeof(std::uint32_t)+refitBounds_.capacity()*sizeof(MeshBounds3D)+mapBytes,target=(std::max)(retainedObjects_,entries_.size()),nodeTarget=target?target*2-1:0,reclaimable=(entries_.capacity()>target?entries_.capacity()-target:0)*sizeof(Entry)+(nodes_.capacity()>nodeTarget?nodes_.capacity()-nodeTarget:0)*sizeof(Node)+(candidates_.capacity()>target?candidates_.capacity()-target:0)*sizeof(std::uint32_t)+(refitBounds_.capacity()>nodeTarget?refitBounds_.capacity()-nodeTarget:0)*sizeof(MeshBounds3D);return{bytes,reclaimable,lastReleasedBytes_,trimCount_};}
std::size_t VisibilityBvh3D::TrimUnusedMemory(){const auto before=MemoryStats().retainedCapacityBytes;auto trim=[]<class T>(std::vector<T>& source,std::size_t count){std::vector<T> replacement;replacement.reserve(count);replacement.insert(replacement.end(),source.begin(),source.end());source.swap(replacement);};const std::size_t target=(std::max)(retainedObjects_,entries_.size()),nodeTarget=target?target*2-1:0;trim(entries_,target);trim(nodes_,nodeTarget);traversal_.clear();trim(traversal_,64);candidates_.clear();trim(candidates_,target);trim(refitBounds_,nodeTarget);std::unordered_map<VisibilityEntityKey3D,std::uint32_t> compactMap;compactMap.reserve(target);compactMap.insert(keyToEntry_.begin(),keyToEntry_.end());keyToEntry_.swap(compactMap);const auto after=MemoryStats().retainedCapacityBytes;lastReleasedBytes_=before>after?before-after:0;++trimCount_;return lastReleasedBytes_;}
